// Tournament preview data
const previewTournament = {
  preview1: {
    id: 'preview1',
    tournament_name: 'Your Tournament',
    game_name: 'Selected Game',
    tournament_format: 'single_elimination',
    max_players: 8,
    status: 'registration',
    entry_fee: 0,
    start_date: new Date().toISOString()
  }
};

const previewParticipants = {
  preview1: []
};

const previewMatches = {
  preview1: [
    { id: 1, round_number: 1, match_number: 1, player1_name: 'Player 1 vs 2', player2_name: 'TBD', status: 'pending' },
    { id: 2, round_number: 1, match_number: 2, player1_name: 'Player 3 vs 4', player2_name: 'TBD', status: 'pending' },
    { id: 3, round_number: 1, match_number: 3, player1_name: 'Player 5 vs 6', player2_name: 'TBD', status: 'pending' },
    { id: 4, round_number: 1, match_number: 4, player1_name: 'Player 7 vs 8', player2_name: 'TBD', status: 'pending' },
    { id: 5, round_number: 2, match_number: 1, player1_name: 'Winner 1', player2_name: 'Winner 2', status: 'pending' },
    { id: 6, round_number: 2, match_number: 2, player1_name: 'Winner 3', player2_name: 'Winner 4', status: 'pending' },
    { id: 7, round_number: 3, match_number: 1, player1_name: 'Final', player2_name: 'TBD', status: 'pending' }
  ]
};

export { previewTournament as demoTournaments, previewParticipants as demoParticipants, previewMatches as demoMatches };
